def minPath(grid, k):
    N = len(grid)
    if N < 2 or k < 1:
        return []

    # Initialize the DP table
    dp = [[float('inf')] * N for _ in range(N)]
    dp[0][0] = grid[0][0]

    # Fill the first row and first column
    for i in range(1, N):
        dp[0][i] = dp[0][i-1] + grid[0][i]
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the DP table
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # Find the minimum path sum
    min_sum = float('inf')
    min_path = []
    for i in range(N):
        for j in range(N):
            if dp[i][j] <= k:
                path = [grid[i][j]]
                x, y = i, j
                while x > 0 or y > 0:
                    if x > 0 and dp[x-1][y] == dp[x][y] - grid[x][y]:
                        path.append(grid[x-1][y])
                        x -= 1
                    else:
                        path.append(grid[x][y-1])
                        y -= 1
                path.reverse()
                if dp[i][j] < min_sum:
                    min_sum = dp[i][j]
                    min_path = path

    return min_path

